  catch(error){if(pfAlive(guard)&&request===pf.learningRequest&&pfLearningVisible()){pf.data.learning=null;pf.learningError=error.message||'성과에서 다음 기획을 불러오지 못했어요.';pfLearningPaint(error.status===401||error.status===403);}}
