  const card=pfLearningCards().find(row=>row.entryId===entryId);if(!card?.canPlan||['waiting','missing'].includes(card.status)||!card.experiments?.some(row=>row.id===experimentId)){pfLearningPaint(true);notify('성과 기록이 바뀌었어요. 현재 표시된 실험 후보를 다시 확인해 주세요.');return false;}
