function pfLinkTargets(){if(!pfReviewVisible())return [];const targets=[];if(pf.reviewData&&pf.reviewPackageId&&pfLinkVisible('package',pf.reviewPackageId))targets.push({kind:'package',id:pf.reviewPackageId});if(pf.view==='performance')for(const entry of pfEntries())if(pfLinkVisible('post',entry.id))targets.push({kind:'post',id:entry.id});return targets;}
