function pfLinkHost(kind,id){if(!pfLinkId(kind,id))return '';const record=pfLinkRecord(kind,id),html=pfLinkContents(kind,id);record.paint=html;return `<section class="pf-link-check" data-pf-link-host="${kind}:${escape(id)}" tabindex="-1" aria-label="링크 접속 확인">${html}</section>`;}
