  catch(error){if(!alive())return false;pf.reviewError=error.message;if(error.status===409){try{const result=await api('/api/publication-packages/'+encodeURIComponent(id)+'/review');if(!alive())return false;if(result.review?.packageId!==id)throw new Error('최신 점검 기록을 확인할 수 없어요.');pf.reviewData=result.review;pf.reviewError='다른 변경이 있어 저장하지 못했어요. 최신 기록을 불러왔으며 작성한 메모는 유지됩니다. 내용을 비교한 뒤 다시 저장해 주세요.';}catch(refreshError){if(alive()){pf.reviewData=null;pf.reviewPackage=null;pf.reviewError=refreshError.message;}}}else if([401,403,404].includes(error.status)){pf.reviewData=null;pf.reviewPackage=null;}return false;}
