function pfReviewClose(){if(pf.reviewBusy)return;pfLinkStop(true);const host=document.querySelector('[data-pf-review-host="'+pf.reviewPackageId+'"]');if(host)host.innerHTML='';const overview=document.querySelector('[data-pf-package-overview="'+pf.reviewPackageId+'"]');if(overview)overview.hidden=false;pf.reviewRequest++;pf.reviewPackageId='';pf.reviewData=null;pf.reviewPackage=null;pf.reviewLoading=false;pf.reviewError='';pf.reviewStatus='';}
function publicationFlowPanel(){pfIdentity();if(!pf.data)return `<section class="maker-loading" role="status"><p>${escape(pf.loading?'게시 준비와 성과 기록을 불러오고 있어요.':pf.targetError||pf.error||'게시 준비와 성과 기록을 불러와 주세요.')}</p>${pfButton('다시 불러오기','refresh',pf.loading?'disabled':'')}</section>`;
  return `<section class="pf-workspace"><div class="pf-heading"><div><h2>완성본에서 다음 기획까지</h2><p>채널별 파일과 게시문을 준비하고, 게시 뒤 24·72시간 반응을 모읍니다.</p></div>${pfButton('새로 읽기','refresh',pf.loading||pf.busy||pf.reviewBusy?'disabled':'','small quiet')}</div><div class="pf-tabs" role="group" aria-label="게시 준비와 성과"><button type="button" data-pf-action="prepare" aria-pressed="${pf.view==='prepare'}">1. 게시 묶음 준비</button><button type="button" data-pf-action="performance" aria-pressed="${pf.view==='performance'}">2. 게시 후 성과 <span>${pfEntries().length}</span></button></div>${pf.error?`<p class="maker-error" role="alert">${escape(pf.error)}</p>`:''}${pf.targetError?`<p class="maker-error" role="alert">${escape(pf.targetError)}</p>`:''}${pfTargetChoicePanel()}<p class="pf-progress" role="status" aria-live="polite" data-pf-status>${escape(pf.status)}</p>${pf.view==='prepare'?pfPreparePanel():pfPerformancePanel()}</section>`;
}
function pfPreparePanel(){const draft=pf.draft,production=pf.production,write=pfWritable(),versions=(production?.versions||[]).filter(row=>row.kind==='video'&&row.mediaId),selected=versions.find(row=>row.id===draft.versionId),profiles=pf.data.catalog?.channels||[],packages=pfPackages();
  return `${pfInboxPanel()}<div class="pf-preparation"><section class="pf-card"><h3>완성본 선택</h3><p class="maker-note">새 작업은 나만 볼 수 있게 시작합니다. 기존 작업의 파일은 해당 작업의 공개 범위를 따릅니다.</p><label class="field">작업<select data-pf-source ${pf.busy?'disabled':''}>${pfOption('','새 완성본 등록',draft.productionId)}${(pf.data.studio?.productions||[]).map(row=>pfOption(row.id,row.title,draft.productionId)).join('')}</select></label>${draft.productionId&&!production?'<p class="maker-note">작업의 파일을 불러오는 중입니다.</p>':''}${versions.length?`<label class="field">게시할 영상 버전<select data-pf-field="versionId" ${pf.busy?'disabled':''}>${versions.map(row=>pfOption(row.id,row.label||row.fileName,draft.versionId)).join('')}</select></label>`:''}${selected?`<video class="pf-video" src="/api/studio-media/${encodeURIComponent(selected.mediaId)}" controls playsinline preload="metadata" aria-label="선택한 완성본"></video><p class="maker-note">${escape(selected.fileName||selected.label)} · 원본을 재생해 화면과 소리를 확인해 주세요.</p>`:''}${write&&(!production||production.canEdit)?`<form data-pf-form="upload"><fieldset ${pf.busy?'disabled':''}><label class="field">${versions.length?'새 버전 추가':'영상 파일'}<input type="file" accept="video/mp4,video/webm,.mp4,.webm" data-pf-file><small>${pf.file?escape(pf.file.name)+' · '+(pf.file.size/1048576).toFixed(1)+' MiB':'MP4·WebM, 100 MiB 이하. 서버에 원본을 보관합니다.'}</small></label><button type="submit" class="btn" ${!pf.file?'disabled':''}>${pf.busy?'처리 중…':'완성본 저장'}</button></fieldset></form>`:''}</section><section class="pf-card"><h3>채널별 게시 묶음</h3><form data-pf-form="package"><fieldset ${!write||pf.busy?'disabled':''}><label class="field">제목<input data-pf-field="title" maxlength="100" required value="${escape(draft.title)}" placeholder="이번 콘텐츠 제목"></label><label class="field">게시문<textarea data-pf-field="body" rows="5" maxlength="${draft.channels.includes('instagram-reels')?2200:5000}" placeholder="채널별 게시문 파일에 담을 내용">${escape(draft.body)}</textarea><small>Instagram 포함 시 2,200자, 그 밖에는 5,000자 이하입니다.</small></label><div class="pf-fields"><label class="field">연결할 주소 <small>선택</small><input type="url" data-pf-field="link" maxlength="2048" value="${escape(draft.link)}" placeholder="https://synk.im/…"></label><label class="field">언어<input data-pf-field="language" maxlength="20" required value="${escape(draft.language)}" placeholder="ko"></label></div><fieldset class="pf-channel-picker"><legend>준비할 채널</legend>${profiles.map(profile=>`<label><input type="checkbox" data-pf-channel="${escape(profile.id)}" ${draft.channels.includes(profile.id)?'checked':''}><span>${escape(profile.label)} <small>${profile.width} × ${profile.height}</small></span></label>`).join('')}</fieldset><label class="field">영상 맞추기<select data-pf-field="mode">${pfOption('adapt','화면을 자르지 않고 채널 크기에 맞추기',draft.mode)}${pfOption('original','규격이 맞는 원본 그대로 사용',draft.mode)}</select><small>비율이 다른 영상은 여백을 넣습니다. 원본은 유지합니다.</small></label>${pf.data.catalog?.capabilities?.conversion===false?'<p class="maker-note">이 서버에서 영상 변환 도구를 사용할 수 없습니다. 원본 규격 검사를 이용해 주세요.</p>':''}<details class="pf-subtitles" ${draft.subtitleText?'open':''}><summary>자막 파일 담기 · 선택</summary><label class="field">SRT·VTT 파일<input type="file" accept=".srt,.vtt,text/vtt" data-pf-subtitle><small>${escape(draft.subtitleFileName||'이미 만든 자막을 검사한 뒤 묶음에 함께 넣습니다.')}</small></label><label class="field">자막 내용<textarea data-pf-field="subtitleText" rows="5" maxlength="200000">${escape(draft.subtitleText)}</textarea></label>${draft.subtitleText?pfButton('자막 비우기','clear-subtitle','','small quiet'):''}</details><button type="submit" class="btn primary" ${!selected?'disabled':''}>${pf.busy?'게시 묶음 만드는 중…':'게시 묶음 만들기'}</button></fieldset></form><p class="maker-note">영상·게시문·자막·검사 결과를 ZIP으로 받습니다. 완성된 파일은 직접 확인한 뒤 게시해 주세요.</p></section></div><section class="pf-card pf-results"><div class="pf-heading"><h3>준비한 게시 묶음 <span>${packages.length}</span></h3></div>${packages.length?packages.map(row=>pfPackageCard(row)).join(''):'<p class="maker-note">준비된 묶음이 없습니다. 완성본을 저장하고 채널을 고르면 여기서 다시 받을 수 있어요.</p>'}</section>`;
}
function pfPackageCard(row,registerButton=true){const url='/api/publication-packages/'+encodeURIComponent(row.id)+'/download',reviewing=pf.reviewPackageId===row.id;return `<article class="pf-package" tabindex="-1" data-pf-package="${escape(row.id)}"><div class="pf-heading"><div><h4>${escape(row.title)}</h4><p>${escape(pfDate(row.createdAt))} · ${escape(row.source?.fileName||'완성본')}</p></div><a class="btn" href="${url}" download>게시 묶음 ZIP 받기</a></div><div data-pf-package-overview="${escape(row.id)}" ${reviewing?'hidden':''}><div class="pf-output-list">${(row.outputs||[]).map(output=>`<div><strong>${escape(output.label||output.channel)}</strong><span>${escape(output.fileName)} · ${output.width} × ${output.height} · ${(Number(output.byteSize||0)/1048576).toFixed(1)} MiB</span>${output.mediaId?`<details><summary>변환된 영상 재생</summary><video class="pf-video" src="/api/studio-media/${encodeURIComponent(output.mediaId)}" controls playsinline preload="none" aria-label="${escape(output.label||output.channel)} 최종 영상"></video></details>`:''}</div>`).join('')}</div><details><summary>기술 검사 결과 보기</summary>${pfChecks(row.checks)}${(row.outputs||[]).map(output=>`<h5>${escape(output.label||output.channel)}</h5>${pfChecks(output.checks)}`).join('')}${row.subtitle?`<p class="maker-note">자막 ${Number(row.subtitle.cueCount||0)}개 · 오류 ${Number(row.subtitle.errors||0)} · 확인 ${Number(row.subtitle.warnings||0)}</p>`:''}</details></div><div class="pf-entry-actions">${pfButton('게시 전 점검','review-open',`data-id="${escape(row.id)}" ${pf.reviewBusy?'disabled':''}`,'small primary')}${registerButton&&pfWritable()?pfButton('게시한 주소 기록하기','use-package',`data-id="${escape(row.id)}" ${pf.reviewBusy?'disabled':''}`,'small quiet'):''}</div>${pfReviewHost(row.id)}</article>`;}
function pfPerformancePanel(){const registration=pf.registration,performance=pf.data.performance||{},entries=pfEntries(),write=pfWritable()&&performance.canWrite!==false,channels=performance.channels||[],selectedPackage=pf.target?.action==='publish'?pfPackages().find(row=>row.id===pf.target.packageId):null;return `${pfLearningPanel()}${selectedPackage?`<section class="pf-card"><h3>오늘 할 일의 게시 묶음</h3>${pfPackageCard(selectedPackage,false)}</section>`:''}<section class="pf-card"><h3>게시한 콘텐츠 등록</h3><p class="maker-note">실제 게시 주소와 게시 시각을 기록하면 24·72시간 수집이 예약됩니다. 서버가 실행 중일 때 작동하며, 플랫폼에서 제공하지 않는 숫자는 직접 보완합니다.</p>${write?`<form data-pf-form="register"><fieldset ${pf.busy?'disabled':''}><div class="pf-fields"><label class="field">게시한 계정<select data-pf-register="channelId" required>${pfOption('','계정 선택',registration.channelId)}${channels.map(row=>pfOption(row.id,row.displayName||row.name||row.label||row.handle||row.canonicalUrl||row.id,registration.channelId)).join('')}</select></label><label class="field">게시 시각 · 한국 시간<input type="datetime-local" data-pf-register="publishedAt" required value="${escape(registration.publishedAt)}"><small data-pf-register-hint>${pfPublishedHint()}</small></label></div><label class="field">게시 주소<input type="url" data-pf-register="url" maxlength="2048" required value="${escape(registration.url)}" placeholder="https://…"></label>${pfLookupAvailable()?`<div class="pf-lookup">${pfButton('주소 확인','lookup',pfLookupBlocked()?'disabled':'','small')}<div class="pf-lookup-note" aria-live="polite">${pfLookupNote()}</div></div>`:''}<div class="pf-fields"><label class="field">콘텐츠 제목<input data-pf-register="title" maxlength="200" value="${escape(registration.title)}"></label><label class="field">게시 묶음 <small>선택</small><select data-pf-register="publicationPackageId">${pfOption('','연결하지 않음',registration.publicationPackageId)}${pfPackages().map(row=>pfOption(row.id,row.title,registration.publicationPackageId)).join('')}</select></label></div>${pfRegisterFormatHost()}<button class="btn primary" type="submit" ${pfRegisterBlocked()?'disabled':''}>게시 기록과 수집 예약 저장</button></fieldset></form>${!channels.length?'<p class="maker-note">등록할 담당 계정이 없습니다. 내 관리 페이지에서 계정을 등록하고 연결해 주세요.</p>':''}`:'<p class="maker-note">현재 권한으로는 저장된 성과를 읽을 수 있어요.</p>'}</section><section class="pf-card"><h3>24·72시간 성과 <span>${entries.length}</span></h3>${entries.length?entries.map(entry=>pfEntryCard(entry,write)).join(''):'<p class="maker-note">게시 기록이 없습니다. 게시한 주소를 등록하면 수집 예정과 결과를 확인할 수 있어요.</p>'}<p class="maker-note">예정 시각과 실제 관측 시각을 함께 보세요. 늦게 확인한 현재 숫자를 과거 시점의 성과로 바꾸지 않습니다. 미확인 값은 0과 구분합니다.</p></section>`;}
function pfEntryCard(entry,write){const channel=(pf.data.performance?.channels||[]).find(row=>row.id===entry.channelId),checkpoints=Array.isArray(entry.checkpoints)?entry.checkpoints:Object.values(entry.checkpoints||{}),canWrite=write&&entry.canEdit!==false;let url='';try{const parsed=new URL(entry.url);if(parsed.protocol==='https:'&&!parsed.username&&!parsed.password)url=parsed.href;}catch{}
  return `<article class="pf-entry" data-pf-entry="${escape(entry.id)}"><div class="pf-heading"><div><h4>${escape(entry.title||'게시한 콘텐츠')}</h4><p>${escape(entry.channelName||channel?.displayName||channel?.name||channel?.label||channel?.handle||entry.channelId)} · ${escape(pfDate(entry.publishedAt))} 게시</p>${url?`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">실제 게시물 열기</a>`:''}</div>${canWrite?`<div class="pf-entry-actions">${pfButton('수집 상태 확인','collect',`data-id="${escape(entry.id)}" ${pf.busy||entry.active===false?'disabled':''}`,'small quiet')}${pfButton(entry.active===false?'자동 수집 재개':'자동 수집 멈춤','active',`data-id="${escape(entry.id)}" ${pf.busy?'disabled':''}`,'small quiet')}</div>`:''}</div>${entry.active!==false?pfLinkHost('post',entry.id):''}${entry.active===false?'<p class="maker-note">자동 수집이 멈춰 있습니다. 재개해도 원래 24·72시간 예정 시각은 바뀌지 않습니다.</p>':''}<div class="pf-checkpoints">${checkpoints.map(point=>pfCheckpoint(entry,point,canWrite)).join('')}</div>${entry.comparison?`<p class="maker-note">${escape(typeof entry.comparison==='string'?entry.comparison:entry.comparison.message||entry.comparison.summary||'')}</p>`:''}</article>`;}
function pfCheckpoint(entry,point,write){
  const labels={pending:'예정',retry:'재시도 예정',collecting:'수집 중',recorded:'기록됨','manual-required':'직접 확인 필요',missed:'시점 놓침'},status=labels[point.status]||point.status||'예정',defs=pfDefinitions(),metrics=point.metrics||{},key=entry.id+':'+point.hours,draft=pf.manual[key],reasons=point.unavailableReasons||{},missing=defs.filter(def=>metrics[pfMetricId(def)]===null||metrics[pfMetricId(def)]===undefined);
  const metricRows=defs.map(def=>{const id=pfMetricId(def),value=metrics[id],source=point.metricProvenance?.[id],comparison=point.comparison?.[id];return `<div><dt>${escape(def.label||id)}</dt><dd>${value===null||value===undefined?'미확인':escape(String(value))}${value!==null&&value!==undefined&&def.unit?` ${escape(pfUnit(def.unit))}`:''}</dd>${reasons[id]?`<small>${escape(reasons[id])}</small>`:''}${source?`<small>${source.source==='manual'?'직접 확인':'자동 수집'} · ${escape(pfDate(source.observedAt))}${source.timing&&source.timing!=='on-time'?' · '+escape(pfTiming(source.timing)):''}</small>`:''}${comparison&&comparison.sampleCount?`<small>같은 조건 ${Number(comparison.sampleCount)}편 중앙값 ${escape(String(comparison.median))}${comparison.deltaPercent!==null&&comparison.deltaPercent!==undefined?' · '+(comparison.deltaPercent>=0?'+':'')+escape(String(comparison.deltaPercent))+'%':''}</small>`:''}</div>`;}).join('');
  const manualRows=missing.map(def=>{const id=pfMetricId(def);return `<label class="field">${escape(def.label||id)}${def.unit?` (${escape(pfUnit(def.unit))})`:''}<input type="number" min="0" ${def.max!==undefined?`max="${Number(def.max)}"`:''} step="${def.unit==='count'?'1':'any'}" data-pf-metric="${escape(id)}" data-key="${escape(key)}" value="${escape(draft?.metrics?.[id]??'')}" placeholder="미확인"></label>`;}).join('');
  return `<section class="pf-checkpoint" tabindex="-1" data-pf-checkpoint="${escape(key)}"><div class="pf-heading"><h5>${Number(point.hours)}시간</h5><span class="pf-badge" data-status="${escape(point.status||'pending')}">${escape(status)}</span></div><p class="maker-note">예정 ${escape(pfDate(point.dueAt))}${point.observedAt?`<br>관측 ${escape(pfDate(point.observedAt))}`:''}${point.timing&&point.timing!=='on-time'?`<br>${escape(pfTiming(point.timing))}`:''}</p>${point.message?`<p class="maker-note">${escape(point.message)}</p>`:''}${point.nextAttemptAt?`<p class="maker-note">다음 확인 ${escape(pfDate(point.nextAttemptAt))}</p>`:''}<dl class="pf-metrics">${metricRows}</dl>${write&&missing.length?`<details ${draft||(pf.target?.action==='performance'&&pf.target.entryId===entry.id&&pf.target.checkpoint===point.hours+'h')?'open':''}><summary>미확인 숫자 직접 보완하기</summary><form data-pf-form="metrics" data-entry="${escape(entry.id)}" data-hours="${Number(point.hours)}"><fieldset ${pf.busy?'disabled':''}><label class="field">숫자를 확인한 시각 · 한국 시간<input type="datetime-local" data-pf-measured="${escape(key)}" required value="${escape(draft?.measuredAt||'')}"><small>과거 화면의 기록을 옮긴다면 그 화면을 확인한 시각을 입력해 주세요.</small></label><div class="pf-manual-grid">${manualRows}</div><label class="field">확인 근거<textarea rows="2" maxlength="1000" data-pf-note="${escape(key)}" placeholder="플랫폼 화면에서 확인한 값과 조건">${escape(draft?.note||'')}</textarea></label><p class="maker-note">확인한 숫자만 입력하세요. 빈칸은 미확인으로 남고 이미 기록된 값은 유지됩니다.</p><button class="btn" type="submit">확인한 숫자 저장</button></fieldset></form></details>`:''}</section>`;
}
async function pfSelectProduction(id){if(pf.busy)return;pf.draft.productionId=id;pf.draft.versionId='';pf.production=null;pf.file=null;pf.error='';const guard=pfGuard(),request=++pf.detailRequest;pfRender();if(!id)return;try{const result=await api('/api/studio-productions/'+encodeURIComponent(id));if(!pfAlive(guard)||request!==pf.detailRequest||pf.draft.productionId!==id)return;pf.production=result.production;const version=[...(result.production.versions||[])].reverse().find(row=>row.kind==='video'&&row.mediaId);pf.draft.versionId=version?.id||'';if(!pf.draft.title)pf.draft.title=result.production.title;}catch(error){if(pfAlive(guard)&&request===pf.detailRequest)pf.error=error.message;}finally{if(pfAlive(guard)&&request===pf.detailRequest)pfRender();}}
function pfSetStatus(message){pf.status=message;const element=document.querySelector('[data-pf-status]');if(element)element.textContent=message;}
function pfUpload(id,file,guard){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();pf.upload=xhr;xhr.open('POST','/api/studio-productions/'+encodeURIComponent(id)+'/media');xhr.withCredentials=true;xhr.timeout=180000;xhr.setRequestHeader('Content-Type',file.type||(/\.webm$/i.test(file.name)?'video/webm':'video/mp4'));xhr.setRequestHeader('X-CSRF-Token',state.csrf);xhr.setRequestHeader('X-File-Name',encodeURIComponent(file.name));xhr.setRequestHeader('X-Version-Label',encodeURIComponent('완성본 · '+file.name.slice(0,85)));xhr.upload.onprogress=event=>{if(pfAlive(guard)&&event.lengthComputable)pfSetStatus('완성본 업로드 '+Math.round(event.loaded/event.total*100)+'%');};xhr.onload=()=>{if(pf.upload===xhr)pf.upload=null;let data;try{data=JSON.parse(xhr.responseText);}catch{return reject(new Error('파일 저장 응답을 읽을 수 없습니다. 새로 읽기로 저장 여부를 확인해 주세요.'));}if(xhr.status<200||xhr.status>=300)return reject(new Error(data.error||data.message||'파일 저장에 실패했어요.'));resolve(data);};xhr.onerror=xhr.ontimeout=()=>{if(pf.upload===xhr)pf.upload=null;reject(new Error('파일을 올리지 못했어요. 연결 상태와 파일 크기를 확인해 주세요.'));};xhr.onabort=()=>reject(new Error('파일 업로드를 취소했어요.'));xhr.send(file);});}
async function pfUploadSelected(){if(pf.busy||!pfWritable()||!pf.file)return;const file=pf.file,guard=pfGuard();pf.busy=true;pf.error='';pfSetStatus('완성본을 저장하고 있어요.');pfRender();try{if(file.size<1||file.size>104857600||!(/\.(mp4|webm)$/i.test(file.name)))throw new Error('MP4·WebM, 100 MiB 이하의 영상을 선택해 주세요.');let id=pf.draft.productionId;if(!id){const result=await api('/api/studio-productions',{title:pf.draft.title.trim()||file.name,stage:'ready'});if(!pfAlive(guard))return;pf.production=result.production;id=result.production.id;pf.draft.productionId=id;if(!pf.draft.title)pf.draft.title=result.production.title;pf.data.studio.productions=[result.production,...pf.data.studio.productions.filter(row=>row.id!==id)];}const result=await pfUpload(id,file,guard);if(!pfAlive(guard))return;pf.production=result.production;const version=[...(result.production.versions||[])].reverse().find(row=>row.kind==='video'&&row.mediaId);pf.draft.versionId=version?.id||'';pf.file=null;pfSetStatus('완성본을 저장했어요. 준비할 채널을 선택해 주세요.');}catch(error){if(pfAlive(guard)){pf.error=error.message;pfSetStatus('');}}finally{if(pfAlive(guard)){pf.busy=false;pfRender();}}}
async function pfCreatePackage(){if(pf.busy||!pfWritable())return;const guard=pfGuard(),payload=structuredClone(pf.draft);if(!payload.productionId||!payload.versionId){pf.error='저장된 완성본을 먼저 선택해 주세요.';pfRender();return;}pf.busy=true;pf.error='';pfSetStatus('채널별 영상과 게시문을 준비하고 있어요. 영상 길이에 따라 시간이 걸립니다.');pfRender();try{const result=await api('/api/publication-packages',payload);if(!pfAlive(guard))return;pf.data.packages.packages=[result.package,...pfPackages().filter(row=>row.id!==result.package.id)];pfSetStatus('게시 묶음이 준비됐어요. ZIP을 받아 실제 결과를 확인해 주세요.');}catch(error){if(pfAlive(guard)){pf.error=error.message;pfSetStatus('입력한 내용은 유지되어 있습니다.');}}finally{if(pfAlive(guard)){pf.busy=false;pfRender();}}}
async function pfRegisterPost(){if(pf.busy||!pfWritable()||pf.data?.performance?.canWrite===false)return;const guard=pfGuard(),input=structuredClone(pf.registration);pfLearningStop(true);pf.busy=true;pf.error='';pfRender();try{if(pfLookupFor()?.result?.ownerMatch===false)throw new Error('이 계정에서 올린 게시물이 아니에요. 게시한 계정을 다시 골라 주세요.');input.publishedAt=pfInstant(input.publishedAt);const formats=pfRegistrationFormats();if(formats.length>1&&!formats.includes(input.publicationFormat))throw new Error('실제 게시한 영상 형식을 선택해 주세요.');if(!input.publicationFormat||!formats.includes(input.publicationFormat))delete input.publicationFormat;if(!input.publicationPackageId)delete input.publicationPackageId;const result=await api('/api/post-performance',input);if(!pfAlive(guard))return;pf.data.performance.entries=[result.entry,...pfEntries().filter(row=>row.id!==result.entry.id)];pf.registration=pfRegistration();pf.lookup=null;pf.lookupFill=null;pfSetStatus(result.linked?'기존 게시 기록에 영상 형식을 연결했어요. 게시 시각과 수집 기록은 유지됩니다.':result.existing?'이미 등록한 게시물입니다. 기존 게시 시각과 수집 기록을 불러왔어요.':'게시 기록과 24·72시간 수집 예약을 저장했어요.'+(result.publishedAtAdjusted?' 게시 시각은 플랫폼에 나온 시각으로 맞췄어요.':''));}catch(error){if(pfAlive(guard))pf.error=error.message;}finally{if(pfAlive(guard)){pf.busy=false;pfRender();pfLearningSchedule(0);}}}
async function pfCollect(id){const entry=pfEntries().find(row=>row.id===id);if(pf.busy||!pfWritable()||entry?.canEdit===false||!entry)return;const guard=pfGuard();pfLearningStop(true);pf.busy=true;pf.error='';pfSetStatus('수집 가능한 시점과 계정 연결을 확인하고 있어요.');pfRender();try{const result=await api('/api/post-performance/'+encodeURIComponent(id)+'/collect',{});if(!pfAlive(guard))return;if(result.entry)pf.data.performance.entries=pfEntries().map(row=>row.id===id?result.entry:row);else await pfLoad();if(pfAlive(guard))pfSetStatus('현재 수집 상태를 확인했어요.');}catch(error){if(pfAlive(guard)){pf.error=error.message;pfSetStatus('');}}finally{if(pfAlive(guard)){pf.busy=false;pfRender();pfLearningSchedule(0);}}}
async function pfSetActive(id){const entry=pfEntries().find(row=>row.id===id);if(pf.busy||!pfWritable()||!entry||entry.canEdit===false)return;const guard=pfGuard();pfLearningStop(true);pf.busy=true;pf.error='';pfRender();try{const result=await api('/api/post-performance/'+encodeURIComponent(id)+'/active',{active:entry.active===false});if(!pfAlive(guard))return;if(result.entry)pf.data.performance.entries=pfEntries().map(row=>row.id===id?result.entry:row);else await pfLoad();if(pfAlive(guard))pfSetStatus(entry.active===false?'자동 수집을 재개했어요.':'자동 수집을 멈췄어요.');}catch(error){if(pfAlive(guard))pf.error=error.message;}finally{if(pfAlive(guard)){pf.busy=false;pfRender();pfLearningSchedule(0);}}}
function pfManual(key){return pf.manual[key]||(pf.manual[key]={metrics:{},measuredAt:'',note:''});}
async function pfSaveMetrics(id,hours){const entry=pfEntries().find(row=>row.id===id);if(pf.busy||!pfWritable()||!entry||entry.canEdit===false)return;const key=id+':'+hours,draft=pf.manual[key],guard=pfGuard();pfLearningStop(true);pf.busy=true;pf.error='';pfRender();try{if(!draft)throw new Error('확인한 숫자와 시각을 입력해 주세요.');const metrics={};for(const [name,value] of Object.entries(draft.metrics)){if(value==='')continue;const point=(entry.checkpoints||[]).find(row=>Number(row.hours)===Number(hours));if(point?.metrics?.[name]!==null&&point?.metrics?.[name]!==undefined)continue;const number=Number(value);if(!Number.isFinite(number)||number<0)throw new Error('숫자는 0 이상으로 입력해 주세요.');metrics[name]=number;}if(!Object.keys(metrics).length)throw new Error('확인한 숫자를 하나 이상 입력해 주세요.');const input={metrics,measuredAt:pfInstant(draft.measuredAt),note:draft.note},result=await api('/api/post-performance/'+encodeURIComponent(id)+'/checkpoints/'+hours,input);if(!pfAlive(guard))return;if(result.entry)pf.data.performance.entries=pfEntries().map(row=>row.id===id?result.entry:row);else await pfLoad();if(!pfAlive(guard))return;delete pf.manual[key];pfSetStatus('확인한 숫자를 저장했어요. 실제 관측 시각이 함께 남습니다.');}catch(error){if(pfAlive(guard))pf.error=error.message;}finally{if(pfAlive(guard)){pf.busy=false;pfRender();pfLearningSchedule(0);}}}
async function pfReadSubtitle(file){if(!file||pf.busy||!pfWritable())return;const guard=pfGuard(),request=++pf.subtitleRequest;try{if(file.size>200000||!/\.(srt|vtt)$/i.test(file.name))throw new Error('200 KB 이하의 SRT·VTT 자막을 선택해 주세요.');const text=await file.text();if(!pfAlive(guard)||request!==pf.subtitleRequest)return;pf.draft.subtitleText=text;pf.draft.subtitleFileName=file.name;pf.error='';}catch(error){if(pfAlive(guard)&&request===pf.subtitleRequest)pf.error=error.message;}finally{if(pfAlive(guard)&&request===pf.subtitleRequest)pfRender();}}
document.addEventListener('input',event=>{const target=event.target;if(!state.user||pf.busy||!pfWritable())return;if(target.dataset.pfReviewField){if(pf.reviewBusy||pf.reviewLoading||!pf.reviewData?.canEdit)return;const draft=pfReviewDraft(target.dataset.check);if(draft&&['status','note'].includes(target.dataset.pfReviewField))draft[target.dataset.pfReviewField]=target.value;return;}const field=target.dataset.pfField,register=target.dataset.pfRegister;if(field&&['title','body','link','language','subtitleText'].includes(field)){pf.draft[field]=target.value;if(field==='subtitleText'&&!pf.draft.subtitleFileName)pf.draft.subtitleFileName=/^\s*WEBVTT/.test(target.value)?'subtitles.vtt':'subtitles.srt';}if(register&&['channelId','url','publishedAt','title','publicationPackageId','publicationFormat'].includes(register))pf.registration[register]=target.value;if(target.dataset.pfMetric)pfManual(target.dataset.key).metrics[target.dataset.pfMetric]=target.value;if(target.dataset.pfMeasured)pfManual(target.dataset.pfMeasured).measuredAt=target.value;if(target.dataset.pfNote)pfManual(target.dataset.pfNote).note=target.value;});
document.addEventListener('change',event=>{const target=event.target;if(!state.user||pf.busy)return;if(target.dataset.pfReviewField){if(pf.reviewBusy||pf.reviewLoading||!pfWritable()||!pf.reviewData?.canEdit)return;const draft=pfReviewDraft(target.dataset.check);if(draft&&['status','note'].includes(target.dataset.pfReviewField))draft[target.dataset.pfReviewField]=target.value;return;}if(target.matches('[data-pf-source]')){void pfSelectProduction(target.value);return;}if(!pfWritable())return;if(target.matches('[data-pf-file]')){pf.file=target.files?.[0]||null;if(pf.file&&!pf.draft.title)pf.draft.title=pf.file.name.replace(/\.[^.]+$/,'');pfRender();}else if(target.matches('[data-pf-subtitle]'))void pfReadSubtitle(target.files?.[0]);else if(target.dataset.pfChannel){const selected=new Set(pf.draft.channels);if(target.checked)selected.add(target.dataset.pfChannel);else selected.delete(target.dataset.pfChannel);pf.draft.channels=[...selected];pfRender();}else if(['versionId','mode'].includes(target.dataset.pfField)){pf.draft[target.dataset.pfField]=target.value;if(target.dataset.pfField==='versionId')pfRender();}else if(['channelId','url','publishedAt','title','publicationPackageId','publicationFormat'].includes(target.dataset.pfRegister)){const field=target.dataset.pfRegister;pf.registration[field]=target.value;if(['channelId','publicationPackageId'].includes(field))pfSyncRegistrationFormat();if(['channelId','url'].includes(field)&&pfLookupAvailable()&&pf.registration.channelId&&String(pf.registration.url||'').trim()&&pf.lookup?.key!==pfLookupKey()){void pfLookup();return;}if(['channelId','url','publicationPackageId'].includes(field))pfRegisterPaint();}});
document.addEventListener('click',event=>{const target=event.target.closest?.('[data-pf-action]');if(!target||target.disabled||!state.user)return;const action=target.dataset.pfAction;if(action==='prepare'||action==='performance'){pf.view=action;pfRender();pfInboxSchedule();pfLearningSchedule();return;}if(pf.busy||pf.reviewBusy)return;if(action==='lookup'){void pfLookup();return;}if(action==='link-check'){void pfLinkLoad(target.dataset.kind,target.dataset.id,true);return;}if(action==='review-open'){void pfReviewOpen(target.dataset.id);return;}if(action==='review-refresh'){void pfReviewOpen(pf.reviewPackageId,false);return;}if(action==='review-close'){pfReviewClose();return;}if(action==='learning-plan'){void pfLearningPlan(target.dataset.entry,target.dataset.experiment);return;}if(action==='learning-refresh'){if(pf.learningFetching||pf.learningBusy)return;pfLearningStop(true);void pfLearningLoad();return;}if(action==='target-cancel'){pf.targetChoice=null;pfSetStatus('작성 중인 내용을 유지했어요.');pfRender();}else if(action==='target-confirm'&&pf.targetChoice)void pfOpenTarget(pf.targetChoice,true);else if(action==='inbox-toggle')void pfInboxAction('toggle');else if(action==='inbox-scan')void pfInboxAction('scan');else if(action==='inbox-copy')void pfInboxCopy();else if(action==='inbox-use')void pfInboxUse(target.dataset.id);else if(action==='inbox-confirm')void pfInboxUse(target.dataset.id,true);else if(action==='inbox-cancel'){pf.inboxChoice='';pfInboxPaint();}else if(action==='refresh')void pfLoad();else if(action==='clear-subtitle'&&pfWritable()){pf.subtitleRequest++;pf.draft.subtitleText='';pf.draft.subtitleFileName='';pfRender();}else if(action==='use-package'&&pfWritable()){const row=pfPackages().find(row=>row.id===target.dataset.id);if(row)void pfOpenTarget({action:'publish',packageId:row.id});}else if(action==='collect')void pfCollect(target.dataset.id);else if(action==='active')void pfSetActive(target.dataset.id);});
document.addEventListener('submit',event=>{const form=event.target;if(!form.matches?.('[data-pf-form]'))return;event.preventDefault();if(!state.user||pf.busy)return;const kind=form.dataset.pfForm;if(kind==='upload')void pfUploadSelected();else if(kind==='package')void pfCreatePackage();else if(kind==='register')void pfRegisterPost();else if(kind==='metrics')void pfSaveMetrics(form.dataset.entry,Number(form.dataset.hours));else if(kind==='review')void pfReviewSave(form.dataset.check);});

document.addEventListener('visibilitychange',()=>{if(typeof state==='undefined')return;if(document.visibilityState==='hidden'){pfInboxStop();pfLearningStop(true);pfLinkStop(true);}else{pfInboxSchedule();pfLearningSchedule(0);pfLinkEnsure();}});
document.addEventListener('click',()=>queueMicrotask(()=>{pfInboxSchedule();pfLearningSchedule();pfLinkEnsure();}));
document.addEventListener('focusout',()=>queueMicrotask(()=>pfLearningPaint()));
document.addEventListener('selectionchange',()=>pfLearningPaint());
for(const type of ['pointerdown','wheel','touchstart','keydown'])document.addEventListener(type,pfReleaseFocusTarget,{capture:true,passive:true});
